import * as THREE from 'three/webgpu';
import { add, mul, texture, positionLocal, normalLocal, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.userData.handlers = {};
  const timelines = [];

  // Load textures
  const imageTexture = ctx.textureLoader.load(config.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.depthMapUrl);

  imageTexture.colorSpace = THREE.SRGBColorSpace;
  depthTexture.colorSpace = THREE.LinearSRGBColorSpace;

  // Create tessellated plane (64x64 segments)
  const geometry = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);

  // TSL material with displacement and filmic grade
  const imageNode = texture(imageTexture);
  const depthNode = texture(depthTexture);

  // Displacement mapping
  const displacementAmount = mul(depthNode.r, 0.18);
  const positionWithDisplacement = add(
    positionLocal,
    mul(normalLocal, displacementAmount)
  );

  // Filmic grade: blacks lifted to #0d0d12, highlights shouldered, +12% contrast, -8% desaturation
  const filmicGrade = (color) => {
    // Black lift
    const lifted = add(mul(color, 0.95), vec3(0.05, 0.05, 0.07));
    // Highlight shoulder
    const shouldered = mul(lifted, 0.98);
    // Midtone contrast +12%
    const contrast = add(mul(shouldered, 1.12), vec3(-0.06, -0.06, -0.06));
    // Desaturation -8%
    const lum = add(
      mul(color.r, 0.299),
      mul(color.g, 0.587),
      mul(color.b, 0.114)
    );
    return add(mul(contrast, 0.92), mul(lum, 0.08));
  };

  const material = new THREE.MeshPhysicalNodeMaterial();
  material.colorSpace = THREE.SRGBColorSpace;
  material.positionNode = positionWithDisplacement;
  material.colorNode = filmicGrade(imageNode);
  material.emissiveNode = mul(depthNode.r, 0.05);
  material.emissiveIntensity = 0.5;
  material.metalness = 0;
  material.roughness = 1;
  material.opacity = 0;
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  group.add(mesh);

  // Create bottom scrim gradient
  const scrimGeom = new THREE.PlaneGeometry(4.0, 1.2);
  const scrimTexture = createGradientTexture();
  const scrimMat = new THREE.MeshBasicMaterial({ map: scrimTexture, transparent: true });
  const scrim = new THREE.Mesh(scrimGeom, scrimMat);
  scrim.position.y = -0.9;
  scrim.position.z = 0.005;
  group.add(scrim);

  // Create caption block
  const captionGroup = new THREE.Group();
  captionGroup.position.set(-1.5, -0.75, 0.01);

  // Text configuration: kicker, headline, body, caption stacked with baseline rhythm
  const textConfig = [
    { text: 'NOVA ATELIER / GENEVA', size: 0.09, font: 'JetBrains Mono', weight: 700, y: 0.45 },
    { text: 'Time, Machined.', size: 0.34, font: 'Lora', weight: 600, y: 0.05 },
    { text: 'Every case begins as a single billet of 904L steel.', size: 0.13, font: 'JetBrains Mono', weight: 400, y: -0.2 },
    { text: 'CALIBRE NA-01 / 72 HOUR RESERVE', size: 0.09, font: 'JetBrains Mono', weight: 400, y: -0.4 }
  ];

  // Create text meshes via fontAtlas
  textConfig.forEach(({ text, size, font, weight, y }) => {
    if (ctx.fontAtlas && typeof ctx.fontAtlas.createMesh === 'function') {
      const textMesh = ctx.fontAtlas.createMesh(text, { font, size, weight, color: new THREE.Color(0xe8ecf2) });
      if (textMesh) {
        textMesh.position.y = y;
        textMesh.position.z = 0.001;
        captionGroup.add(textMesh);
      }
    }
  });

  // Accent hairline bar (#ff2a38, emissive 1.8) between headline and body
  const barGeom = new THREE.PlaneGeometry(0.75, 0.02);
  const barMat = new THREE.MeshStandardMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    toneMapped: false
  });
  const bar = new THREE.Mesh(barGeom, barMat);
  bar.position.y = -0.08;
  bar.position.z = 0.001;
  captionGroup.add(bar);

  group.add(captionGroup);

  // Plate opacity fade in: 0 → 1 over 500ms
  const plateTimeline = gsap.timeline();
  plateTimeline.fromTo(
    material,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' }
  );
  timelines.push(plateTimeline);

  // Caption rise-in: y +0.4 → 0 over 700ms, starting 120ms after plate
  const captionTimeline = gsap.timeline();
  captionTimeline.fromTo(
    captionGroup.position,
    { y: -0.35 },
    { y: -0.75, duration: 0.7, ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)' },
    0.12
  );
  timelines.push(captionTimeline);

  // Apply parallax-scroll cinematic primitive
  if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.35 });
  }

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    depthTexture.dispose();
    barGeom.dispose();
    barMat.dispose();
    scrimGeom.dispose();
    scrimMat.dispose();
    scrimTexture.dispose();
  };

  return group;
}

function createGradientTexture() {
  const width = 512;
  const height = 256;
  const data = new Uint8Array(width * height * 4);

  for (let i = 0; i < height; i++) {
    const y = i / height;
    let alpha = 0;
    if (y >= 0.45) {
      alpha = ((y - 0.45) / (1.0 - 0.45)) * 255;
    }

    for (let j = 0; j < width; j++) {
      const idx = (i * width + j) * 4;
      data[idx + 0] = 11;
      data[idx + 1] = 11;
      data[idx + 2] = 16;
      data[idx + 3] = Math.round(alpha);
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat, THREE.UnsignedByteType);
  texture.needsUpdate = true;
  return texture;
}
